class Solution {
public:
    int maximalRectangle(vector<vector<char>>& matrix) {
        if (matrix.empty() || matrix[0].empty()) return 0;
        int m = matrix.size(), n = matrix[0].size();
        int maxArea = 0;
        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                if (matrix[i][j] == '0') continue;
                int minWidth = n;
                for (int k = i; k < m; ++k) {
                    int width = 0;
                    while (j + width < n && matrix[k][j + width] == '1') width++;
                    if (width == 0) break;
                    minWidth = min(minWidth, width);
                    maxArea = max(maxArea, minWidth * (k - i + 1));
                }
            }
        }
        return maxArea;
    }
};

